final _readium = FlutterReadium();
Publication? _publication;

Future<void> _open() async {
  _publication = await _readium.openPublication('https://example.com/book.epub');
}

@override
Widget build(BuildContext context) {
  if (_publication == null) return const CircularProgressIndicator();
  return ReadiumReaderWidget(publication: _publication!);
}
